  4395  /* divide different length alternatives in look-behind.
  4396    (?<=A|B) ==> (?<=A)|(?<=B)
  4397    (?<!A|B) ==> (?<!A)(?<!B)
  4398  */
  4399  static int
  4400  divide_look_behind_alternatives(Node* node)
  4401  {
  4402    Node *head, *np, *insert_node;
  4403    AnchorNode* an = ANCHOR_(node);
  4404    int anc_type = an->type;
  4405
  4406    head = NODE_ANCHOR_BODY(an);
  4407    np = NODE_CAR(head);
  4408    node_swap(node, head);
  4409    NODE_CAR(node) = head;
  4410    NODE_BODY(head) = np;
  4411
  4412    np = node;
  4413    while (IS_NOT_NULL(np = NODE_CDR(np))) {
  4414      insert_node = onig_node_copy(head);
  4415      CHECK_NULL_RETURN_MEMERR(insert_node);
  4416      NODE_BODY(insert_node) = NODE_CAR(np);
  4417      NODE_CAR(np) = insert_node;
  4418    }
  4419
  4420    if (anc_type == ANCR_LOOK_BEHIND_NOT) {
  4421      np = node;
  4422      do {
  4423        NODE_SET_TYPE(np, NODE_LIST);  /* alt -> list */
  4424      } while (IS_NOT_NULL(np = NODE_CDR(np)));
  4425    }
  4426    return 0;
  4427  }
