  4429  static int
  4430  quant_reduce_in_look_behind(Node* node)
  4431  {
  4432    NodeType type;
  4433    Node* body;
  4434
  4435    if (NODE_TYPE(node) != NODE_QUANT) return 0;
  4436
  4437    body = NODE_BODY(node);
  4438    type = NODE_TYPE(body);
  4439    if (type == NODE_STRING || type == NODE_CTYPE ||
  4440        type == NODE_CCLASS || type == NODE_BACKREF) {
  4441      QuantNode* qn = QUANT_(node);
  4442      qn->upper = qn->lower;
  4443    }
  4444
  4445    return 0;
  4446  }
