  4448  static int
  4449  tree_reduce_in_look_behind(Node* node, regex_t* reg, ScanEnv* env)
  4450  {
  4451    int r;
  4452
  4453    switch (NODE_TYPE(node)) {
  4454    case NODE_QUANT:
  4455      r = quant_reduce_in_look_behind(node);
  4456      break;
  4457
  4458    case NODE_ALT:
  4459      do {
  4460        r = quant_reduce_in_look_behind(NODE_CAR(node));
  4461      } while (r == 0 && IS_NOT_NULL(node = NODE_CDR(node)));
  4462      break;
  4463
  4464    default:
  4465      r = 0;
  4466      break;
  4467    }
  4468
  4469    return r;
  4470  }
