  4472  static int tune_tree(Node* node, regex_t* reg, int state, ScanEnv* env);
  4473
  4474  static int
  4475  tune_look_behind(Node* node, regex_t* reg, int state, ScanEnv* env)
  4476  {
  4477    int r;
  4478    int state1;
  4479    MinMaxCharLen ci;
  4480    Node* body;
  4481    AnchorNode* an = ANCHOR_(node);
  4482
  4483    if (an->type == ANCR_LOOK_BEHIND_NOT)
  4484      state1 = state | IN_NOT | IN_LOOK_BEHIND;
  4485    else
  4486      state1 = state | IN_LOOK_BEHIND;
  4487
  4488    body = NODE_ANCHOR_BODY(an);
  4489    /* Execute tune_tree(body) before call node_char_len().
  4490       Because case-fold expansion must be done before node_char_len().
  4491     */
  4492    r = tune_tree(body, reg, state1, env);
  4493    if (r != 0) return r;
  4494
  4495    r = tree_reduce_in_look_behind(body, reg, env);
  4496    if (r != 0) return r;
  4497
  4498    r = node_char_len(body, reg, &ci, env);
  4499    if (r >= 0) {
  4500      if (ci.min == 0 && ci.min_is_sure != 0) {
  4501        if (an->type == ANCR_LOOK_BEHIND_NOT)
  4502          r = onig_node_reset_fail(node);
  4503        else
  4504          r = onig_node_reset_empty(node);
  4505
  4506        return r;
  4507      }
  4508
  4509      if (r == CHAR_LEN_TOP_ALT_FIXED) {
  4510        if (IS_SYNTAX_BV(env->syntax, ONIG_SYN_DIFFERENT_LEN_ALT_LOOK_BEHIND)) {
  4511          r = divide_look_behind_alternatives(node);
  4512          if (r == 0)
  4513            r = tune_tree(node, reg, state, env);
  4514        }
  4515        else if (IS_SYNTAX_BV(env->syntax, ONIG_SYN_VARIABLE_LEN_LOOK_BEHIND))
  4516          goto normal;
  4517        else
  4518          r = ONIGERR_INVALID_LOOK_BEHIND_PATTERN;
  4519      }
  4520      else { /* CHAR_LEN_NORMAL */
  4521      normal:
  4522        if (ci.min == INFINITE_LEN) {
  4523          r = ONIGERR_INVALID_LOOK_BEHIND_PATTERN;
  4524        }
  4525        else {
  4526          if (ci.min != ci.max &&
  4527              ! IS_SYNTAX_BV(env->syntax, ONIG_SYN_VARIABLE_LEN_LOOK_BEHIND)) {
  4528            r = ONIGERR_INVALID_LOOK_BEHIND_PATTERN;
  4529          }
  4530          else {
  4531            an->char_min_len = ci.min;
  4532            an->char_max_len = ci.max;
  4533          }
  4534        }
  4535      }
  4536    }
  4537
  4538    return r;
  4539  }
