  4755  static int
  4756  unravel_cf_look_behind_add(Node** rlist, Node** rsn,
  4757                  int n, OnigCaseFoldCodeItem items[], OnigEncoding enc,
  4758                  UChar* s, int one_len)
  4759  {
  4760    int r, i, found;
  4761
  4762    found = 0;
  4763    for (i = 0; i < n; i++) {
  4764      OnigCaseFoldCodeItem* item = items + i;
  4765      if (item->byte_len == one_len) {
  4766        if (item->code_len == 1) {
  4767          found = 1;
  4768        }
  4769      }
  4770    }
  4771
  4772    if (found == 0) {
  4773      r = unravel_cf_string_add(rlist, rsn, s, s + one_len, 0 /* flag */);
  4774    }
  4775    else {
  4776      Node* node;
  4777      OnigCodePoint codes[14];/* least ONIGENC_GET_CASE_FOLD_CODES_MAX_NUM + 1 */
  4778
  4779      found = 0;
  4780      codes[found++] = ONIGENC_MBC_TO_CODE(enc, s, s + one_len);
  4781      for (i = 0; i < n; i++) {
  4782        OnigCaseFoldCodeItem* item = items + i;
  4783        if (item->byte_len == one_len) {
  4784          if (item->code_len == 1) {
  4785            codes[found++] = item->code[0];
  4786          }
  4787        }
  4788      }
  4789      r = onig_new_cclass_with_code_list(&node, enc, found, codes);
  4790      if (r != 0) return r;
  4791
  4792      r = unravel_cf_node_add(rlist, node);
  4793      if (r != 0) onig_node_free(node);
  4794
  4795      *rsn = NULL_NODE;
  4796    }
  4797
  4798    return r;
  4799  }
